// components/Screens/Dashboard/Hooks/useEvaluationTab.ts
// Custom hook – all state and business logic for the Evaluation tab
// Exact port of old InterviewPanelList component logic

import { useState, useEffect, useCallback } from "react";
import moment from "moment";
import { NavigateFunction } from "react-router-dom";
import { EvaluationCandidate, getAllInterviewPanelForCandidate, getCandidatesByIDs, getEvaluationActionData, getGradeLevel, getInterviewPanelByUser, getRecruitmentByID, getUserGuidByEmail, InterviewPanelRecord } from "../services/InterviewPanelService";
import { InterviewLevels, InterviewPanelRoutes, StatusId } from "../EvaluationConfig/Config";




// ─── Alert state type ─────────────────────────────────────────────────────────
export type AlertState = {
  open: boolean;
  message: string;
  type: "Success" | "Error" | "Warning" | "Confirmation" | "";
  onConfirm?: () => void;
};

// ─── Hook return type ─────────────────────────────────────────────────────────
export type UseEvaluationTabReturn = {
  candidates: EvaluationCandidate[];
  panelRecords: InterviewPanelRecord[];
  pendingInfo: any[];
  isLoading: boolean;
  alert: AlertState;
  closeAlert: () => void;
  handleHover: (statusId: number, rowData: EvaluationCandidate) => Promise<void>;
  handleEvaluateClick: (
    rowData: EvaluationCandidate,
    navigate: NavigateFunction
  ) => Promise<void>;
  refresh: () => void;
};

// ═════════════════════════════════════════════════════════════════════════════
// Hook
// ═════════════════════════════════════════════════════════════════════════════
export function useEvaluationTab(
  currentUserEmailId: string
): UseEvaluationTabReturn {
  const [candidates, setCandidates] = useState<EvaluationCandidate[]>([]);
  const [panelRecords, setPanelRecords] = useState<InterviewPanelRecord[]>([]);
  const [pendingInfo, setPendingInfo] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [alert, setAlert] = useState<AlertState>({
    open: false,
    message: "",
    type: "",
  });

  // ── helpers ────────────────────────────────────────────────────────────────
  const showAlert = (
    message: string,
    type: AlertState["type"] = "Error"
  ) => setAlert({ open: true, message, type });

  const closeAlert = useCallback(
    () => setAlert((prev) => ({ ...prev, open: false })),
    []
  );

  // ══════════════════════════════════════════════════════════════════════════
  // fetchCandidateData  (= old fetchCandidateData)
  // ══════════════════════════════════════════════════════════════════════════
  const fetchCandidateData = useCallback(async () => {
    if (!currentUserEmailId) return;
    setIsLoading(true);

    try {
      // Step 1 – get SP user ID from email
      const userRes = await getUserGuidByEmail(currentUserEmailId);
      if (userRes.status !== 200 || !userRes.data) {
        setIsLoading(false);
        return;
      }
      const userID = userRes.data.key;

      // Step 2 – get panel records where current user is a panel member
      //          filter: InterviewPanel/Id eq userID
      const panelRes = await getInterviewPanelByUser(userID);
      if (panelRes.status !== 200 || panelRes.data.length === 0) {
        setCandidates([]);
        setPanelRecords([]);
        setIsLoading(false);
        return;
      }

      setPanelRecords(panelRes.data);
      const candidateIDs = panelRes.data.map((p) => p.CandidateID);

      // Step 3 – get candidates filtered by status & ItemCreated
      //          StatusId in [40, 129] AND ItemCreated eq 'No' AND ID in candidateIDs
      const candRes = await getCandidatesByIDs(candidateIDs);
      if (candRes.status !== 200 || candRes.data.length === 0) {
        setCandidates([]);
        setIsLoading(false);
        return;
      }

      // Step 4 – enrich each candidate with Grade + Level + InterviewDateTime
      const enriched: EvaluationCandidate[] = await Promise.all(
        candRes.data.map(async (item: any, index: number) => {
          let grade = "";
          let level = ""; // "Level 1" | "Level 2" | "Level 3" from DB
          let jobCodeID = 0;

          try {
            // Step 4a – get PatersonGrade from HRMSVacancyReplacementRequest
            const vrrRes = await getRecruitmentByID(
              item.RecruitmentID?.Id || item.RecruitmentID || 0
            );
            if (vrrRes.status === 200 && vrrRes.data.length > 0) {
              grade = vrrRes.data[0].PatersonGrade || "";
              jobCodeID = vrrRes.data[0].JobCodeId || 0;

              // Step 4b – get Levels from HRMSGradeMaster using PatersonGrade
              if (grade) {
                const gradeRes = await getGradeLevel(grade);
                if (gradeRes.status === 200 && gradeRes.data.length > 0) {
                  level = gradeRes.data[0].Level || ""; // DB col: item.Levels
                }
              }
            }
          } catch (err) {
            console.warn("Enrich failed for candidate:", item.ID, err);
          }

          // Step 4c – InterviewDateTime:
          //   use Level2 fields if present, else Level1 fields
          //   format: "DD-MMM-YYYY hh:mm A"
          const interviewDate =
            item.InterviewDateLevel2 || item.InterviewDate || "";
          const interviewTime =
            item.InterviewTimeLevel2 || item.InterviewTime || "";
          const interviewDateTime = moment(
            `${interviewDate} ${interviewTime}`,
            "YYYY-MM-DD HH:mm"
          ).format("DD-MMM-YYYY hh:mm A");

          // Step 4d – InterviewLevel display:
          //   DB "Level 2" → display "Level 1 & 2"
          //   DB "Level 1" or "Level 3" → display as-is
          const displayLevel =
            level === InterviewLevels.Level2
              ? InterviewLevels.Levels2
              : level;

          return {
            SNO: index + 1,
            ID: item.ID,
            FristName: item.FristName || "",
            LastName: item.LastName || "",
            ApplicantName:
              `${item.FristName || ""} ${item.LastName || ""}`.trim(),
            PositionTitle: item.PositionTitle || "",
            InterviewDateTime: interviewDateTime,
            InterviewLevel: displayLevel,
            Grade: grade,
            Status:
              item.Status?.StatusDescription ||
              (typeof item.Status === "string" ? item.Status : "") ||
              "",
            StatusId: item.StatusId || 0,
            RecruitmentID:
              item.RecruitmentID?.Id || item.RecruitmentID || 0,
            JobCodeID: jobCodeID,
            InterviewDate: item.InterviewDate || "",
            InterviewDateLevel2: item.InterviewDateLevel2 || "",
            InterviewTime: item.InterviewTime || "",
            InterviewTimeLevel2: item.InterviewTimeLevel2 || "",
          };
        })
      );

      // Step 5 – finalValue filter (old code: keep candidate only if matching
      //   panel record has correct level for the candidate's statusId)
      //   StatusId 40  (Level 1): keep if panel InterviewLevel === "Level 1"
      //   StatusId 129 (Level 2): keep if panel InterviewLevel === "Level 2"
      const finalCandidates = enriched.filter((candidate) =>
        panelRes.data.some((panel) => {
          if (candidate.ID !== panel.CandidateID) return false;
          if (
            candidate.StatusId === StatusId.InterviewScheduled &&
            panel.InterviewLevel === InterviewLevels.Level1
          )
            return true;
          if (
            candidate.StatusId === StatusId.InterviewScheduledforLevel2 &&
            panel.InterviewLevel === InterviewLevels.Level2
          )
            return true;
          return false;
        })
      );

      setCandidates(finalCandidates);
    } catch (err) {
      console.error("useEvaluationTab fetchCandidateData error:", err);
    } finally {
      setIsLoading(false);
    }
  }, [currentUserEmailId]);

  useEffect(() => {
    void fetchCandidateData();
  }, [fetchCandidateData]);

  // ══════════════════════════════════════════════════════════════════════════
  // handleHover  (= old handleHover on Status cell)
  // Determines level from statusId → calls GetEvalutionActionData
  // ══════════════════════════════════════════════════════════════════════════
  const handleHover = useCallback(
    async (statusId: number, rowData: EvaluationCandidate) => {
      // Old code: Levels = statusId === 40 ? "Level 1" : "Level 2"
      const level =
        statusId === StatusId.InterviewScheduled
          ? InterviewLevels.Level1
          : InterviewLevels.Level2;

      const res = await getEvaluationActionData(rowData.ID, level);
      setPendingInfo(res.data || []);
    },
    []
  );

  // ══════════════════════════════════════════════════════════════════════════
  // handleEvaluateClick  (= old checkIsScoreSheetUploaded + handleRedirectView)
  // ══════════════════════════════════════════════════════════════════════════
  const handleEvaluateClick = useCallback(
    async (rowData: EvaluationCandidate, navigate: NavigateFunction) => {
      try {
        // Step A – get current user's SP ID key
        const userRes = await getUserGuidByEmail(currentUserEmailId);
        if (!userRes.data) return;
        const currentUserKey = userRes.data.key.toString();

        // Step B – get ALL panel records for this candidate (all items, JS-filtered)
        const allPanelsRes = await getAllInterviewPanelForCandidate(rowData.ID);
        if (!allPanelsRes.data || allPanelsRes.data.length === 0) return;

        // candidatePanels = all panels whose CandidateIDId === rowData.ID
        // (already done inside getAllInterviewPanelForCandidate)
        const candidatePanels = allPanelsRes.data;

        // Step C – filter to panels where current user is listed
        const userPanels = candidatePanels.filter((panel) =>
          panel.InterviewPanelStringId?.includes(currentUserKey)
        );
        if (userPanels.length === 0) return;

        // Step D – determine target level from StatusId
        const targetLevel =
          rowData.StatusId === StatusId.InterviewScheduled
            ? InterviewLevels.Level1
            : InterviewLevels.Level2;

        // Step E – filter to panels of target level
        const levelPanels = userPanels.filter(
          (p) => p.InterviewLevel === targetLevel
        );

        // Step F – check IsScoreSheetUploaded
        const alreadyScored = levelPanels.some(
          (p) => p.IsScoreSheetUploaded === "Yes"
        );

        if (alreadyScored) {
          // Old handleAlert logic:
          // Level 1 → "The scorecard for the candidate has already been submitted."
          // Level 2 → "The scorecard for the candidate comments has already been submitted."
          showAlert(
            targetLevel === InterviewLevels.Level1
              ? "The scorecard for the candidate has already been submitted."
              : "The scorecard for the candidate comments has already been submitted."
          );
          return;
        }

        // Step G – handleRedirectView: check interview date
        // Old code: todayDateStr >= interviewDateStr → navigate, else show date error
        const todayStr = moment().format("YYYY-MM-DD");
        const interviewDateStr = moment(
          rowData.InterviewDateTime,
          "DD-MMM-YYYY hh:mm A"
        ).format("YYYY-MM-DD");

        if (todayStr < interviewDateStr) {
          const formatted = moment(interviewDateStr, "YYYY-MM-DD").format(
            "DD-MMM-YYYY"
          );
          showAlert(
            `You can only evaluate this candidate on or after the interview date: ${formatted}`
          );
          return;
        }

        // Step H – navigate to correct route
        // StatusId 40  → InterviewPanelEdit
        // StatusId 129 → HodViewScorecard
        const path =
          rowData.StatusId === StatusId.InterviewScheduled
            ? InterviewPanelRoutes.InterviewPanelEdit
            : InterviewPanelRoutes.HodViewScorecard;

        navigate(path, {
          state: {
            ID: rowData.ID,
            StatusId: rowData.StatusId,
            Status: rowData.Status,
            RecruitmentID: rowData.RecruitmentID,
            InterviewLevel: rowData.InterviewLevel,
            JobCodeID: rowData.JobCodeID,
          },
        });
      } catch (err) {
        console.error("handleEvaluateClick error:", err);
      }
    },
    [currentUserEmailId]
  );

  return {
    candidates,
    panelRecords,
    pendingInfo,
    isLoading,
    alert,
    closeAlert,
    handleHover,
    handleEvaluateClick,
    refresh: fetchCandidateData,
  };
}